function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', P1 = '#2a2620', P2 = '#4a443c', P3 = '#6a6358';
  const G1 = '#d4a017', G2 = '#f0d060';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  px(0, 0, 32, 32, P2);
  px(0, 0, 32, 1, P3);
  px(0, 0, 1, 32, P3);
  const spike = (bx) => {
    px(bx, 22, 4, 4, O);
    px(bx + 1, 14, 2, 10, G1);
    px(bx + 1, 14, 2, 2, G2);
    px(bx + 1, 10, 2, 4, G2);
    px(bx + 2, 8, 1, 3, G2);
    px(bx + 2, 7, 1, 1, O);
  };
  spike(3);
  spike(9);
  spike(15);
  spike(21);
  spike(27);
  px(1, 26, 30, 6, P1);
  px(2, 27, 28, 4, P2);
}
